package com.bangon.kiosk.controller;
import com.bangon.kiosk.dto.ApiDtos.*;import com.bangon.kiosk.entity.Customer;import com.bangon.kiosk.repository.CustomerRepository;
import jakarta.servlet.http.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.authentication.*;import org.springframework.security.core.context.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.context.HttpSessionSecurityContextRepository;import org.springframework.security.web.csrf.CsrfToken;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final CustomerRepository customers;private final PasswordEncoder encoder;private final AuthenticationManager auth;
 public AuthController(CustomerRepository c,PasswordEncoder p,org.springframework.security.core.userdetails.UserDetailsService users){customers=c;encoder=p;auth=new ProviderManager(new DaoAuthenticationProvider(users){ {setPasswordEncoder(p);} });}
 @GetMapping("/csrf") public Map<String,String> csrf(CsrfToken token){return Map.of("token",token.getToken());}
 @PostMapping("/register") public Map<String,Object> register(@Valid @RequestBody Register r){if(customers.findByEmailIgnoreCase(r.email()).isPresent())throw new IllegalArgumentException("Email already registered");Customer c=new Customer();c.name=r.name().trim();c.email=r.email().toLowerCase(Locale.ROOT).trim();c.passwordHash=encoder.encode(r.password());customers.save(c);return Map.of("message","Registered. Please sign in.");}
 @PostMapping("/login") public Map<String,Object> login(@Valid @RequestBody Login r,HttpServletRequest request,HttpServletResponse response){var authentication=auth.authenticate(new UsernamePasswordAuthenticationToken(r.email(),r.password()));request.getSession().invalidate();SecurityContext context=SecurityContextHolder.createEmptyContext();context.setAuthentication(authentication);SecurityContextHolder.setContext(context);new HttpSessionSecurityContextRepository().saveContext(context,request,response);return Map.of("message","Signed in");}
 @PostMapping("/logout") public Map<String,String> logout(HttpServletRequest req){req.getSession().invalidate();SecurityContextHolder.clearContext();return Map.of("message","Signed out");}
}
